    h, w = len(grid), len(grid[0])
    # The repeated motif pitch is the smallest period (5 or 6) that best
    # explains the non-separator cells as one periodic color pattern.
    candidates = range(2, 9)
    def score(p):
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v != 3:
                    groups.setdefault((r % p, c % p), []).append(v)
        return sum(max(vals.count(v) for v in set(vals)) for vals in groups.values())
    period = max(candidates, key=lambda p: (score(p), -p))
    groups = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3:
                groups.setdefault((r % period, c % period), []).append(grid[r][c])
    template = {k: max(set(v), key=v.count) for k, v in groups.items()}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = template.get((r % period, c % period), 0)
    for r in range(h):
        for c in range(w):
            if out[r][c] == 2 and (c - r) % period == 0:
                out[r][c] = 8
    return out

