    # More direct detection also handles a vertical separator.
    horizontal = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    vertical = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    n = max(len(horizontal), len(vertical))
    pitch = n + 1
    # Select the densest aligned n-by-n 2-pattern as the repeated motif.
    best = None
    for r0 in range(0, h - n + 1, pitch):
        for c0 in range(0, w - n + 1, pitch):
            block = [[grid[r0+r][c0+c] for c in range(n)] for r in range(n)]
            count = sum(v == 2 for row in block for v in row)
            if count and (best is None or count > best[0]):
                best = (count, block)
    if best is None:
        return [row[:] for row in grid]
    motif = best[1]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0
    nr = (h + 1) // pitch
    nc = (w + 1) // pitch
    for tr in range(min(n, nr)):
        for tc in range(min(n, nc)):
